<?php require '../includes/functions.php';require_login();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$img=upload_image('image');$type=$_POST['type']??'';$title=trim($_POST['title']??'');$cat=trim($_POST['category']??'');$color=trim($_POST['color']??'');$loc=trim($_POST['location']??'');$date=$_POST['event_date']??'';$desc=trim($_POST['description']??'');$ai=trim($_POST['ai_label']??'');$conf=floatval($_POST['ai_confidence']??0);$embedding=trim($_POST['ai_embedding']??'');$hash=trim($_POST['image_hash']??'');$sens=isset($_POST['is_sensitive'])?1:0;if(!in_array($type,['lost','found'])||!$title||!$cat||!$loc||!$date||!$desc)throw new Exception('Completa todos los campos obligatorios.');$st=$pdo->prepare('INSERT INTO reports(user_id,type,title,category,color,location,event_date,description,image,ai_label,ai_confidence,ai_embedding,image_hash,is_sensitive) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([user()['id'],$type,$title,$cat,$color,$loc,$date,$desc,$img,$ai,$conf,$embedding,$hash,$sens]);$id=$pdo->lastInsertId();flash('Reporte publicado correctamente.');header('Location: '.url('reports/view.php?id='.$id));exit;}catch(Exception $e){$err=$e->getMessage();}}$title='Nuevo reporte';require '../includes/header.php';?><main class="dashboard"><div class="welcome"><div><h1>Crear un reporte</h1><p class="muted">Publica la información que ayude a conectar el objeto con su dueño.</p></div></div><form class="panel" method="post" enctype="multipart/form-data" style="max-width:850px;margin:auto"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="ai_label" id="ai_label"><input type="hidden" name="ai_confidence" id="ai_confidence"><input type="hidden" name="ai_embedding" id="ai_embedding"><input type="hidden" name="image_hash" id="image_hash"><?php if($err):?><div class="flash err"><?=e($err)?></div><?php endif;?><div class="grid2"><div><label>Tipo de reporte *</label><select name="type" required><option value="lost">🔴 Perdí un objeto</option><option value="found">🟢 Encontré un objeto</option></select></div><div><label>Categoría *</label><select name="category" required><option>Celular</option><option>Documento</option><option>Llaves</option><option>Audífonos</option><option>Cargador</option><option>Bolso/Morral</option><option>Cuaderno/Libro</option><option>Sombrilla</option><option>Ropa</option><option>Otro</option></select></div></div><label>Título *</label><input class="input" name="title" placeholder="Ej. Morral azul con bolsillo frontal" required><div class="grid2"><div><label>Color</label><input class="input" name="color" placeholder="Azul, negro..."></div><div><label>Fecha del hecho *</label><input class="input" type="date" name="event_date" value="<?=date('Y-m-d')?>" required></div></div><label>Lugar *</label><input class="input" name="location" placeholder="Bloque, salón, biblioteca, cafetería..." required><label>Descripción *</label><textarea name="description" rows="5" required placeholder="Describe marcas, características visibles y circunstancias. No publiques información privada que solo el dueño deba conocer."></textarea><label>Fotografía</label><input class="input" type="file" name="image" id="image" accept="image/jpeg,image/png,image/webp"><img id="imagePreview" style="display:none;max-width:280px;margin-top:12px;border-radius:14px"><div class="ai-box"><b>✨ Análisis inteligente de la fotografía</b><p class="small muted" id="aiStatus">Selecciona una imagen. Encuéntralo analizará sus características visuales para compararla con otros reportes.</p></div><label><input type="checkbox" name="is_sensitive"> Es un documento o contiene datos sensibles: ocultar la imagen al público.</label><button class="btn primary" style="margin-top:20px">Publicar reporte</button></form></main><script src="https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js"></script><script src="https://cdn.jsdelivr.net/npm/@tensorflow-models/mobilenet@2.1.1"></script><script>
const f=document.getElementById('image'),s=document.getElementById('aiStatus');
async function imageHash(img){const c=document.createElement('canvas');c.width=16;c.height=16;const x=c.getContext('2d');x.drawImage(img,0,0,16,16);const d=x.getImageData(0,0,16,16).data,g=[];for(let i=0;i<d.length;i+=4)g.push(.299*d[i]+.587*d[i+1]+.114*d[i+2]);const avg=g.reduce((a,b)=>a+b,0)/g.length;return g.map(v=>v>=avg?'1':'0').join('');}
f.addEventListener('change',async()=>{if(!f.files[0])return;s.innerHTML='<b>Analizando fotografía…</b> La IA está preparando una huella visual para buscar objetos parecidos.';try{const img=document.getElementById('imagePreview');if(!img.complete||!img.src)await new Promise(r=>img.onload=r);document.getElementById('image_hash').value=await imageHash(img);const model=await mobilenet.load({version:2,alpha:1.0});const p=await model.classify(img,10);const emb=model.infer(img,true);const vec=Array.from(await emb.data());emb.dispose();document.getElementById('ai_embedding').value=JSON.stringify(vec.map(v=>+v.toFixed(6)));if(p.length){document.getElementById('ai_label').value=p.map(x=>x.className).join(' | ');document.getElementById('ai_confidence').value=(p[0].probability*100).toFixed(2);}s.innerHTML='<b>✓ Análisis completado.</b> Encuéntralo ya puede comparar esta fotografía con las imágenes de otros reportes. La identificación técnica se mantiene interna y no se muestra al público.';}catch(e){console.error(e);s.innerHTML='<b>La fotografía se guardará normalmente.</b> No se pudo completar el análisis visual en este momento; las coincidencias también usarán los datos del reporte.';}});
</script><?php require '../includes/footer.php';?>